edits.after:
events: { 
  input: { 
    selection: event => { window.cityPicker.input.value = event.detail.selection.value; },
    keydown: event => { 
      if (event.key === 'Escape') { 
        event.preventDefault(); 
        if (typeof window.cityPicker.close === 'function') {
          window.cityPicker.close();
        }
      } 
    } 
  } 
}
